import React, { useRef, useCallback } from 'react';
import { ChatMode as ChatModeEnum, UploadedFile, ChatMessage, GroundingSource } from '../types';
import { generateResponseStream } from '../services/geminiService';
import { exportBriefingToPdf } from '../services/exportService';
import { cleanJsonOutput, isJsonBriefing, getFriendlyErrorMessage } from '../utils';
import { FILE_ANALYSIS_PROMPT, BRIEFING_TRIGGERS, SHIFT_BRIEFING_PROMPT, HELP_COMMAND_RESPONSE, DRUG_ANALYSIS_PROMPT } from '../constants';
import { AppState, AppAction } from './useAppStore';

interface UseChatOrchestratorProps {
    state: AppState;
    dispatch: React.Dispatch<AppAction>;
    uploadedFile: UploadedFile | null;
    setUploadedFile: (file: UploadedFile | null) => void;
    isLive: boolean;
    stopSession: () => void;
    userLocation?: { latitude: number, longitude: number };
    clearFile: () => void;
}

export const useChatOrchestrator = ({
    state,
    dispatch,
    uploadedFile,
    setUploadedFile,
    isLive,
    stopSession,
    userLocation,
    clearFile
}: UseChatOrchestratorProps) => {
    const abortControllerRef = useRef<AbortController | null>(null);
    const { messages, chatMode } = state;

    const handleStop = useCallback(() => {
        if (abortControllerRef.current) abortControllerRef.current.abort();
        dispatch({ type: 'REQUEST_FINISH' });
    }, [dispatch]);

    const handleClearChat = useCallback(() => {
        dispatch({ type: 'RESET_CHAT' });
        clearFile();
    }, [dispatch, clearFile]);

    const handleSend = useCallback(async (userPrompt: string) => {
        const trimmedPrompt = userPrompt.trim();
        if (!trimmedPrompt && !uploadedFile) return;

        if (isLive) {
            stopSession();
            dispatch({ type: 'SET_CHAT_MODE', payload: ChatModeEnum.Auto });
        }

        // --- Export Command ---
        if (trimmedPrompt.toLowerCase() === '/export') {
            const history = messages.filter(m => !isJsonBriefing(m.content));
            if (history.length === 0) {
                 dispatch({ type: 'ADD_INTERIM_MESSAGE', payload: { role: 'model', content: '⚠️ **Cannot Export:** No history available.' } });
                 return;
            }

            dispatch({ type: 'ADD_INTERIM_MESSAGE', payload: { role: 'model', content: '📥 Generating briefing for PDF export...' } });
            dispatch({ type: 'SET_LOADING', payload: true });

            abortControllerRef.current = new AbortController();
            try {
                const modeForRequest = ChatModeEnum.Standard;
                const stream = generateResponseStream(SHIFT_BRIEFING_PROMPT(), history, modeForRequest, { responseType: 'json' });
                let fullResponseText = '';
                for await (const chunk of stream) {
                    if (abortControllerRef.current?.signal.aborted) throw new Error("Aborted");
                    fullResponseText += chunk.text;
                }

                if (fullResponseText.includes("NO DATA")) throw new Error("Insufficient clinical data found.");

                const cleanedJson = cleanJsonOutput(fullResponseText);
                if (!cleanedJson.startsWith('{')) throw new Error("Invalid briefing format.");

                const parsedBriefing = JSON.parse(cleanedJson);
                if (parsedBriefing.briefingTitle && parsedBriefing.briefingTitle.includes("NO DATA")) throw new Error("Insufficient clinical data.");

                await exportBriefingToPdf(parsedBriefing);
                dispatch({ type: 'UPDATE_LAST_MESSAGE_CONTENT', payload: '✅ Shift briefing PDF downloaded.' });
            } catch (e) {
                if (e.message === "Aborted") {
                     dispatch({ type: 'UPDATE_LAST_MESSAGE_CONTENT', payload: '🛑 Export cancelled.' });
                } else {
                    const friendlyError = getFriendlyErrorMessage(e);
                    dispatch({ type: 'UPDATE_LAST_MESSAGE_CONTENT', payload: `Sorry, PDF generation failed.\n\n**Reason:** ${friendlyError}` });
                }
            } finally {
                dispatch({ type: 'SET_LOADING', payload: false });
                abortControllerRef.current = null;
            }
            return;
        }

        // --- Help Command ---
        if (trimmedPrompt.toLowerCase() === '/help') {
             dispatch({ type: 'ADD_FULL_RESPONSE', payload: { message: { role: 'user', content: '/help' } }});
             dispatch({ type: 'ADD_FULL_RESPONSE', payload: { message: { role: 'model', content: HELP_COMMAND_RESPONSE } } });
             return;
        }

        // --- Standard Message & File Handling ---
        let finalApiPrompt = trimmedPrompt;
        let historyContent = trimmedPrompt;
        let fileForApi: UploadedFile | undefined = uploadedFile || undefined;
        let displayOverride = undefined;
        let modeForRequest: ChatModeEnum = chatMode === ChatModeEnum.Live ? ChatModeEnum.Auto : chatMode;
        let responseType: 'json' | 'text' = 'text';

        const isBriefingCommand = BRIEFING_TRIGGERS.some(trigger => trimmedPrompt.toLowerCase().includes(trigger)) || trimmedPrompt.toLowerCase() === '/brief';
        const isDrugCommand = trimmedPrompt.toLowerCase().startsWith('/drugs');

        if (uploadedFile) {
             try {
                let analysisPrompt: string;
                if (uploadedFile.type === 'application/pdf') {
                    const promptBase = trimmedPrompt ? `User Query: ${trimmedPrompt}` : `Analyze this medical document.`;
                    analysisPrompt = FILE_ANALYSIS_PROMPT(uploadedFile.file.name) + `\n\n${promptBase}`;
                } else if (uploadedFile.type === 'text/plain' || uploadedFile.file.name.endsWith('.txt') || uploadedFile.file.name.endsWith('.md')) {
                     const textContent = await uploadedFile.file.text();
                     const promptBase = trimmedPrompt ? `User Query: ${trimmedPrompt}` : `Analyze this document.`;
                     const fullEmbeddedContent = `*** BEGIN FILE CONTENT: ${uploadedFile.file.name} ***\n${textContent}\n*** END FILE CONTENT ***\n\n${promptBase}`;
                     analysisPrompt = fullEmbeddedContent;
                     historyContent = fullEmbeddedContent;
                     displayOverride = `📄 **Uploaded ${uploadedFile.file.name}**\n\n${trimmedPrompt || "Requested analysis."}`;
                     fileForApi = undefined; 
                } else {
                    const baseAnalysisPrompt = FILE_ANALYSIS_PROMPT(uploadedFile.file.name);
                    if (!trimmedPrompt) {
                        analysisPrompt = baseAnalysisPrompt;
                        displayOverride = `Analyzing file: ${uploadedFile.file.name}`; 
                    } else {
                        analysisPrompt = `${baseAnalysisPrompt}\n\n---\n**ADDITIONAL INSTRUCTION:**\nThe user has asked: "${trimmedPrompt}".\n1. You MUST still output VALID JSON.\n2. Answer the user's question within the "visualObservations" or "note" fields.`;
                    }
                }

                finalApiPrompt = analysisPrompt;
                if (isBriefingCommand) {
                    finalApiPrompt = `${finalApiPrompt}\n\nIMPORTANT: After analyzing, ${SHIFT_BRIEFING_PROMPT()}`;
                    modeForRequest = ChatModeEnum.Standard;
                    responseType = 'json';
                    if (!displayOverride) historyContent = trimmedPrompt || "/brief (with file)";
                }
             } catch (error) {
                 dispatch({ type: 'REQUEST_FAILED', payload: getFriendlyErrorMessage(error) });
                 return;
             }
        } else if (isBriefingCommand) {
            finalApiPrompt = SHIFT_BRIEFING_PROMPT();
            historyContent = "/brief"; 
            modeForRequest = ChatModeEnum.Standard;
            responseType = 'json';
        } else if (isDrugCommand) {
            finalApiPrompt = DRUG_ANALYSIS_PROMPT(trimmedPrompt);
            modeForRequest = ChatModeEnum.Auto; // Use Auto to allow Search access for drugs
            responseType = 'json';
        }

        if (trimmedPrompt.toLowerCase().startsWith('/patient')) modeForRequest = ChatModeEnum.Standard;

        // UI Updates
        const userMessage: ChatMessage = { role: 'user', content: historyContent };
        if (displayOverride) userMessage.displayContent = displayOverride;
        if (uploadedFile) {
            const persistenceUrl = uploadedFile.type.startsWith('image/') && uploadedFile.base64 ? `data:${uploadedFile.type};base64,${uploadedFile.base64}` : undefined;
            userMessage.filePreview = { name: uploadedFile.file.name, type: uploadedFile.type, url: persistenceUrl, base64: fileForApi ? uploadedFile.base64 : undefined };
        }

        dispatch({ type: 'START_REQUEST', payload: { userMessage } });
        dispatch({ type: 'ADD_RESPONSE_PLACEHOLDER' });
        setUploadedFile(null);

        // API Call
        abortControllerRef.current = new AbortController();
        try {
            const history = [...messages];
            const stream = generateResponseStream(finalApiPrompt, history, modeForRequest, { file: fileForApi, responseType, location: userLocation });

            for await (const chunk of stream) {
                if (abortControllerRef.current?.signal.aborted) throw new Error("Aborted");

                const groundingMetadata = chunk.candidates?.[0]?.groundingMetadata;
                let sources: GroundingSource[] | undefined = undefined;

                if (groundingMetadata && groundingMetadata.groundingChunks) {
                    sources = groundingMetadata.groundingChunks.map(chunk => {
                        if (chunk.web) return { web: chunk.web };
                        if ((chunk as any).maps) return { maps: (chunk as any).maps };
                        return undefined;
                    }).filter(Boolean) as GroundingSource[];
                }

                dispatch({ type: 'APPEND_TO_LAST_MESSAGE', payload: { chunk: chunk.text || '', sources } });
            }
        } catch (e) {
             if (e.message === "Aborted") {
                 dispatch({ type: 'APPEND_TO_LAST_MESSAGE', payload: { chunk: " [Stopped]" } });
            } else {
                dispatch({ type: 'REQUEST_FAILED', payload: getFriendlyErrorMessage(e) });
            }
        } finally {
            dispatch({ type: 'REQUEST_FINISH' });
            abortControllerRef.current = null;
        }
    }, [messages, chatMode, uploadedFile, isLive, stopSession, userLocation, dispatch, setUploadedFile]);

    return {
        handleSend,
        handleStop,
        handleClearChat,
        handleExportChat: useCallback(() => handleSend('/export'), [handleSend])
    };
};

import React from 'react';
import { ChatMode } from '../types';
import { MODEL_CONFIGS } from '../constants';
import { BoltIcon, DeepAnalysisIcon, MagnifyingGlassIcon, SparklesIcon, AutoModeIcon, LiveIcon } from './icons';

interface ModeSelectorProps {
    currentMode: ChatMode;
    onModeChange: (mode: ChatMode) => void;
}

const ICONS: Record<ChatMode, React.FC<{className: string}>> = {
    [ChatMode.Auto]: AutoModeIcon,
    [ChatMode.Standard]: SparklesIcon,
    [ChatMode.Quick]: BoltIcon,
    [ChatMode.Deep]: DeepAnalysisIcon,
    [ChatMode.Web]: MagnifyingGlassIcon,
    [ChatMode.Live]: LiveIcon,
};

const ModeSelector: React.FC<ModeSelectorProps> = ({ currentMode, onModeChange }) => {
    return (
        <div className="flex items-center bg-slate-100 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 p-1">
            {Object.values(ChatMode).map((mode) => {
                const Icon = ICONS[mode];
                const isActive = currentMode === mode;
                return (
                    <button
                        key={mode}
                        onClick={() => onModeChange(mode)}
                        className={`relative group px-3 py-1.5 rounded-sm text-xs font-mono uppercase tracking-wide transition-all duration-200 flex items-center gap-2 flex-shrink-0
                            ${isActive 
                                ? 'bg-slate-800 text-white dark:bg-slate-200 dark:text-slate-900 shadow-sm' 
                                : 'text-slate-500 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white hover:bg-slate-200 dark:hover:bg-slate-800'
                            }`}
                    >
                        <Icon className={`w-3.5 h-3.5 ${isActive ? 'text-blue-400 dark:text-blue-600' : ''}`} />
                        <span className="hidden lg:inline">{mode}</span>
                         <span className="absolute top-full left-1/2 -translate-x-1/2 mt-3 w-max max-w-xs bg-slate-900 text-white text-[10px] rounded-sm py-1 px-2 opacity-0 group-hover:opacity-100 transition-opacity duration-200 pointer-events-none z-40 border border-slate-700 shadow-xl hidden md:block">
                            {MODEL_CONFIGS[mode].description}
                        </span>
                    </button>
                )
            })}
        </div>
    );
};

export default ModeSelector;

import React, { useState, useRef, useCallback, KeyboardEvent, useLayoutEffect, useEffect } from 'react';
import type { UploadedFile, ChatMode } from '../types';
import { ChatMode as ChatModeEnum } from '../types';
import { PaperclipIcon, SendIcon, XCircleIcon, BriefingIcon, UserIcon, DrugsIcon, DownloadIcon, DocumentTextIcon, MicrophoneIcon, CameraIcon, LiveIcon, StopIcon } from './icons';
import { useSpeechRecognition } from '../hooks/useSpeechRecognition';

interface InputBarProps {
    onSend: (prompt: string) => void;
    onClearFile: () => void;
    setUploadedFile: (file: UploadedFile) => void;
    isLoading: boolean;
    currentMode: ChatMode;
    uploadedFile: UploadedFile | null;
    toggleLiveSession: () => void;
    isLiveSessionActive: boolean;
    onStop?: () => void;
}

const QUICK_COMMANDS = [
  { command: '/brief', description: 'Shift briefing', icon: BriefingIcon },
  { command: '/patient ', description: 'Patient summary', icon: UserIcon },
  { command: '/drugs ', description: 'Check drugs', icon: DrugsIcon },
  { command: '/export', description: 'Export PDF', icon: DownloadIcon },
];

const InputBar: React.FC<InputBarProps> = ({ onSend, onClearFile, setUploadedFile, isLoading, currentMode, uploadedFile, toggleLiveSession, isLiveSessionActive, onStop }) => {
    const [prompt, setPrompt] = useState('');
    const [showCommands, setShowCommands] = useState(false);
    const fileInputRef = useRef<HTMLInputElement>(null);
    const cameraInputRef = useRef<HTMLInputElement>(null);
    const textareaRef = useRef<HTMLTextAreaElement>(null);

    // Custom Hook for Speech
    const { isListening, toggleListening, stopListening } = useSpeechRecognition({
        onResult: (transcript) => setPrompt(transcript),
        onError: (err) => alert(err)
    });

    useEffect(() => {
        let activeUrl = uploadedFile?.url;
        return () => {
            if (activeUrl) {
                setTimeout(() => { URL.revokeObjectURL(activeUrl!); }, 1000);
            }
        };
    }, [uploadedFile]);

    const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
        const file = event.target.files?.[0];
        if (file) {
            if (file.size > 4 * 1024 * 1024) {
                alert("File is too large. Please select a file smaller than 4MB.");
                return;
            }
            const reader = new FileReader();
            reader.onloadend = () => {
                const base64 = (reader.result as string).split(',')[1];
                const uploadPayload: UploadedFile = { file, base64, type: file.type };
                if (file.type.startsWith('image/')) {
                    uploadPayload.url = URL.createObjectURL(file);
                }
                setUploadedFile(uploadPayload);
            };
            reader.readAsDataURL(file);
        }
        if (event.target) event.target.value = '';
    };

    const handleSendClick = useCallback(() => {
        const canSend = !isLoading || isLiveSessionActive;
        if (canSend) {
            if (isListening) stopListening();
            onSend(prompt);
            setPrompt('');
            setShowCommands(false);
        }
    }, [isLoading, isLiveSessionActive, onSend, prompt, isListening, stopListening]);

    const handleCommandSelect = (command: string) => {
        setPrompt(command);
        setShowCommands(false);
        setTimeout(() => textareaRef.current?.focus(), 0);
    };

    const handleKeyDown = (event: KeyboardEvent<HTMLTextAreaElement>) => {
        if (event.key === 'Enter' && !event.shiftKey) {
            event.preventDefault();
            handleSendClick();
        }
    };

    const resizeTextarea = () => {
        const textarea = textareaRef.current;
        if (textarea) {
            textarea.style.height = 'auto';
            if (prompt === '') {
                textarea.style.height = '';
                return;
            }
            const scrollHeight = textarea.scrollHeight;
            textarea.style.height = `${Math.min(scrollHeight, 150)}px`;
        }
    };

    const handleTextareaInput = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
        const value = e.target.value;
        setPrompt(value);
        setShowCommands(value.trim() === '/' || value.endsWith(' /'));
    };

    useLayoutEffect(() => { resizeTextarea(); }, [prompt]);

    const handleBlur = () => { setTimeout(() => setShowCommands(false), 200); };

    const isInputDisabled = (isLoading && !isLiveSessionActive) || isListening;
    const placeholderText = isLiveSessionActive 
        ? 'Listening...' 
        : (isListening ? 'Dictating...' : 'Enter clinical instruction or query...');

    const showStopButton = isLoading && !isLiveSessionActive && onStop;

    return (
        <footer className="flex-shrink-0 p-2 md:p-6 pb-4 md:pb-8 z-30 pointer-events-none">
            <div className="max-w-4xl mx-auto pointer-events-auto">
                <div className={`relative transition-all duration-300 ${isLiveSessionActive ? 'translate-y-0' : ''}`}>

                    {/* File Attachment Pill */}
                     {uploadedFile && (
                        <div className="absolute bottom-full left-0 mb-3 animate-slide-up z-20">
                             <div className="flex items-center gap-3 bg-slate-900 text-white p-2 pr-4 rounded-sm shadow-xl border-l-4 border-blue-500">
                                {uploadedFile.url && uploadedFile.type.startsWith('image/') ? (
                                     <img src={uploadedFile.url} alt="Attachment" className="w-8 h-8 object-cover rounded-sm" />
                                ) : (
                                    <div className="w-8 h-8 flex items-center justify-center bg-slate-800 rounded-sm">
                                        <DocumentTextIcon className="w-4 h-4 text-slate-400" />
                                    </div>
                                )}
                                <div className="flex flex-col">
                                    <span className="text-xs font-mono font-bold max-w-[150px] truncate">{uploadedFile.file.name}</span>
                                    <span className="text-[10px] text-slate-400 uppercase">{uploadedFile.type.split('/')[1]}</span>
                                </div>
                                <button onClick={onClearFile} className="ml-2 text-slate-400 hover:text-red-400">
                                    <XCircleIcon className="w-5 h-5" />
                                </button>
                            </div>
                        </div>
                    )}

                    {/* Quick Command Menu */}
                     {showCommands && (
                        <div className="absolute bottom-full left-0 mb-2 bg-white dark:bg-slate-900 rounded-sm shadow-2xl border border-slate-300 dark:border-slate-700 w-64 animate-slide-up z-20 overflow-hidden">
                            <div className="bg-slate-100 dark:bg-slate-800 px-3 py-1.5 border-b border-slate-200 dark:border-slate-700 flex justify-between items-center">
                                 <p className="text-[10px] font-mono font-bold uppercase tracking-wider text-slate-500">Quick Execute</p>
                                 <div className="flex gap-1">
                                     <div className="w-1.5 h-1.5 rounded-full bg-slate-300"></div>
                                     <div className="w-1.5 h-1.5 rounded-full bg-slate-300"></div>
                                 </div>
                            </div>
                            <ul className="p-0">
                                {QUICK_COMMANDS.map(({ command, description, icon: Icon }) => (
                                    <li key={command} className="border-b border-slate-100 dark:border-slate-800 last:border-0">
                                        <button
                                            onClick={() => handleCommandSelect(command)}
                                            className="w-full text-left flex items-center gap-3 p-3 hover:bg-blue-50 dark:hover:bg-slate-800/50 transition-colors group"
                                        >
                                            <div className="text-slate-400 group-hover:text-blue-500">
                                                <Icon className="w-4 h-4" />
                                            </div>
                                            <div>
                                                <p className="font-mono text-xs font-bold text-slate-700 dark:text-slate-200 group-hover:text-blue-600 dark:group-hover:text-blue-400">{command}</p>
                                                <p className="text-[10px] text-slate-400">{description}</p>
                                            </div>
                                        </button>
                                    </li>
                                ))}
                            </ul>
                        </div>
                    )}

                    {/* Main Command Console */}
                    <div className={`
                        flex items-end gap-0 rounded-sm shadow-2xl transition-all duration-300 border-t-2 relative overflow-hidden
                        ${isLiveSessionActive 
                            ? 'bg-slate-900 border-red-500 shadow-red-900/20' 
                            : 'bg-white dark:bg-slate-900 border-blue-500 shadow-blue-900/10'
                        }
                    `}>
                        {/* Decorative Console Strip */}
                        <div className="absolute top-0 right-0 p-1 flex gap-1 z-10 pointer-events-none opacity-50">
                             <div className={`w-6 h-1 md:w-8 ${isLiveSessionActive ? 'bg-red-500' : 'bg-blue-500'}`}></div>
                             <div className="w-1 h-1 bg-slate-400"></div>
                             <div className="w-1 h-1 bg-slate-400"></div>
                        </div>

                        {/* Start Live Session Button */}
                        <button
                            onClick={toggleLiveSession}
                            className={`flex-shrink-0 h-full min-h-[50px] md:min-h-[56px] w-12 md:w-14 flex items-center justify-center transition-all border-r border-slate-200 dark:border-slate-800 ${
                                isLiveSessionActive 
                                ? 'bg-red-600 text-white animate-pulse' 
                                : 'bg-slate-50 dark:bg-slate-800 text-slate-500 dark:text-slate-400 hover:text-red-500 hover:bg-red-50 dark:hover:bg-slate-700'
                            }`}
                            title="Toggle Live Consult"
                        >
                            <LiveIcon className="w-5 h-5 md:w-6 md:h-6" />
                        </button>

                        {/* Input Area */}
                        <div className="flex-1 flex flex-col relative min-w-0 px-2">
                            <textarea
                                ref={textareaRef}
                                value={prompt}
                                onChange={handleTextareaInput}
                                onKeyDown={handleKeyDown}
                                onBlur={handleBlur}
                                placeholder={placeholderText}
                                rows={1}
                                className={`w-full bg-transparent resize-none outline-none py-3 md:py-4 px-1 md:px-2 text-sm font-medium leading-relaxed max-h-32 font-mono no-scrollbar ${
                                    isLiveSessionActive ? 'text-white placeholder-slate-500' : 'text-slate-900 dark:text-white placeholder-slate-400'
                                }`}
                                disabled={isInputDisabled}
                            />
                        </div>

                        {/* Tools */}
                        <div className="flex items-center gap-0.5 md:gap-1 self-end pb-2 pr-1 md:pr-2">
                            <input type="file" ref={fileInputRef} onChange={handleFileChange} accept="image/*,application/pdf,.txt,.md" className="hidden" />
                            <input type="file" ref={cameraInputRef} onChange={handleFileChange} accept="image/*" capture="environment" className="hidden" />

                            {!isLiveSessionActive && (
                                <>
                                    <button onClick={() => fileInputRef.current?.click()} className="p-1.5 md:p-2 text-slate-400 hover:text-blue-500 transition-colors rounded-sm hover:bg-slate-100 dark:hover:bg-slate-800" title="Attach">
                                        <PaperclipIcon className="w-5 h-5" />
                                    </button>
                                    <button onClick={() => cameraInputRef.current?.click()} className="p-1.5 md:p-2 text-slate-400 hover:text-blue-500 transition-colors rounded-sm hover:bg-slate-100 dark:hover:bg-slate-800" title="Camera">
                                        <CameraIcon className="w-5 h-5" />
                                    </button>
                                    {currentMode !== ChatModeEnum.Live && (
                                        <button 
                                            onClick={() => toggleListening(prompt)} 
                                            className={`p-1.5 md:p-2 transition-colors rounded-sm hover:bg-slate-100 dark:hover:bg-slate-800 ${isListening ? 'text-red-500 bg-red-50 dark:bg-red-900/20 animate-pulse border border-red-200 dark:border-red-900' : 'text-slate-400 hover:text-blue-500'}`}
                                            title="Dictate"
                                        >
                                            <MicrophoneIcon className="w-5 h-5" />
                                        </button>
                                    )}
                                </>
                            )}

                             {/* Execute Button */}
                            {(!isLiveSessionActive && currentMode !== ChatModeEnum.Live) && (
                                <button 
                                    onClick={showStopButton ? onStop : handleSendClick}
                                    disabled={!showStopButton && (isInputDisabled || (!prompt.trim() && !uploadedFile))}
                                    className={`ml-1 flex-shrink-0 h-9 w-9 md:h-10 md:w-10 rounded-sm flex items-center justify-center transition-all ${
                                        showStopButton
                                        ? 'bg-slate-700 text-white'
                                        : 'bg-blue-600 hover:bg-blue-500 text-white disabled:opacity-50 disabled:bg-slate-200 dark:disabled:bg-slate-800 dark:disabled:text-slate-600'
                                    }`}
                                >
                                    {showStopButton ? <StopIcon className="w-4 h-4" /> : <SendIcon className="w-4 h-4" />}
                                </button>
                            )}
                        </div>
                    </div>
                </div>
            </div>
        </footer>
    );
};

export default InputBar;
